#include <iostream>
#include <fstream>
#include <filesystem>
#include <vector>
#include <string>
#include <algorithm> // Necessário para std::find
#include <limits>    // Para limpar o buffer de entrada

// Dependências Crypto++
#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

// Estrutura para armazenar o nome do arquivo e seu hash
struct FileHashEntry {
    std::string filename;
    std::string filePath;
    std::string hash;
};

// Função para calcular o Keccak-512
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    // Usa FileSource para ler o arquivo e HashFilter/HexEncoder para gerar o digest hexadecimal
    CryptoPP::FileSource(filePath.c_str(), true,
        new CryptoPP::HashFilter(hash,
            new CryptoPP::HexEncoder(
                new CryptoPP::StringSink(digest), true)));

    return digest;
}

int main() {
    std::vector<FileHashEntry> foundFiles;
    std::vector<std::string> extensions = { ".exe", ".dll", ".asi" };

    // 1. LEITURA E CÁLCULO DE HASH
    std::cout << "Iniciando varredura no diretório atual..." << std::endl;
    try {
        for (const auto& entry : fs::directory_iterator(fs::current_path())) {
            if (entry.is_regular_file()) {
                std::string extension = entry.path().extension().string();
                // Verifica se a extensão está na lista
                if (std::find(extensions.begin(), extensions.end(), extension) != extensions.end()) {
                    std::string filePath = entry.path().string();
                    std::string hash = calculateKeccak512(filePath);

                    // Armazena a entrada
                    foundFiles.push_back({entry.path().filename().string(), filePath, hash});
                }
            }
        }
    } catch (const fs::filesystem_error& e) {
        std::cerr << "Erro ao acessar o diretório: " << e.what() << std::endl;
        return 1;
    }

    // 2. SALVAR TODOS OS HASHS EM rTalesHash.txt
    std::ofstream hashOutputFile("rTalesHash.txt");
    if (!hashOutputFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo de hash (rTalesHash.txt)!" << std::endl;
        return 1;
    }

    for (const auto& entry : foundFiles) {
        // Formato: "NomeDoArquivo" : hash
        hashOutputFile << "\"" << entry.filename << "\" : " << entry.hash << std::endl;
    }
    hashOutputFile.close();
    std::cout << "\n[SUCESSO] Todos os hashes foram calculados e salvos em rTalesHash.txt" << std::endl;


    // 3. INTERFACE INTERATIVA E GERAÇÃO DE rTales.ini
    if (foundFiles.empty()) {
        std::cout << "\nNenhum arquivo com as extensões especificadas (.exe, .dll, .asi) foi encontrado." << std::endl;
        return 0;
    }

    std::cout << "\n===================================================" << std::endl;
    std::cout << "  LISTA DE ARQUIVOS ENCONTRADOS (Selecione para rTales.ini)" << std::endl;
    std::cout << "===================================================" << std::endl;

    // Exibe a lista numerada
    for (size_t i = 0; i < foundFiles.size(); ++i) {
        std::cout << "[" << i + 1 << "] " << foundFiles[i].filename << std::endl;
    }
    std::cout << "---------------------------------------------------" << std::endl;
    std::cout << "Digite os números dos arquivos que deseja incluir em rTales.ini (separados por vírgula), ou 'ALL' para todos, ou 'S' para sair: ";

    std::string input;
    std::getline(std::cin, input);

    std::vector<const FileHashEntry*> filesToInclude;

    if (input == "ALL" || input == "all") {
        for (const auto& entry : foundFiles) {
            filesToInclude.push_back(&entry);
        }
    } else if (input == "S" || input == "s") {
        std::cout << "Operação cancelada. rTales.ini não será criado." << std::endl;
        return 0;
    } else {
        // Processa a lista de números
        std::stringstream ss(input);
        std::string segment;
        while (std::getline(ss, segment, ',')) {
            try {
                int index = std::stoi(segment);
                if (index >= 1 && index <= static_cast<int>(foundFiles.size())) {
                    filesToInclude.push_back(&foundFiles[index - 1]);
                } else {
                    std::cerr << "Aviso: Número " << index << " fora do intervalo válido." << std::endl;
                }
            } catch (const std::invalid_argument& e) {
                std::cerr << "Erro: Formato de entrada inválido. Use números separados por vírgula ou 'ALL'." << std::endl;
            } catch (const std::out_of_range& e) {
                std::cerr << "Erro: Número muito grande." << std::endl;
            }
        }
    }

    // 4. CRIAÇÃO DO ARQUIVO rTales.ini (SOMENTE SE HOUVER SELEÇÕES)
    if (!filesToInclude.empty()) {
        std::ofstream iniOutputFile("rTales.ini");
        if (iniOutputFile.is_open()) {
            for (const auto* entry : filesToInclude) {
                // Formato: "NomeDoArquivo" : hash
                iniOutputFile << "\"" << entry->filename << "\" : " << entry->hash << std::endl;
            }
            iniOutputFile.close();
            std::cout << "\n[SUCESSO] Arquivo rTales.ini criado com os " << filesToInclude.size() 
                      << " arquivos selecionados." << std::endl;
        } else {
            std::cerr << "\n[ERRO] Não foi possível abrir o arquivo rTales.ini para escrita." << std::endl;
        }
    } else {
        std::cout << "\nNenhuma seleção válida feita. rTales.ini não foi criado." << std::endl;
    }

    return 0;
}
